text:
{
  "entries": [
    {
      "name_han": "道德真經口義",
      "full_vn": "Đạo Đức Chân Kinh Khẩu Nghĩa (Lý Vinh đời Đường) giải Đạo Đức Kinh theo lối khẩu nghĩa: 'Đạo khả đạo, phi thường đạo' nghĩa là Đạo có thể nói ra thì không còn là Đạo thường hằng; 'Danh khả danh, phi thường danh' — tên gọi có thể đặt thì không còn là tên thường. Đạo sinh một, một sinh hai, hai sinh ba, ba sinh vạn vật. Thánh nhân xử vô vi mà thiên hạ hóa; 'thượng thiện nhược thủy' — thiện cao nhất như nước, lợi vạn vật mà không tranh. Giữ nhu, giữ hư, bớt dục thì được lâu dài. Cốt lõi: lấy vô vi trị thân trị quốc, lấy hư tĩnh hợp Đạo."
    },
    {
      "name_han": "許真君玉匣記",
      "full_vn": "Hứa Chân Quân Ngọc Hiệp Ký ghi lịch ngày lành dữ, kỵ kỵ xuất hành, hôn thú, động thổ, khai trương theo tháng, ngày, sao. Văn dạy: ngày tốt làm việc thì thuận, ngày xấu làm việc thì nghịch; gặp ngày phạm sát, tai, hung tinh thì nên tĩnh, không khởi công lớn. Lịch còn chỉ ngày cúng tế, tẩy trạch, nhập trạch, an táng, khai thị. Mục đích: giúp dân biết thời tiết, tránh hung cầu cát. Cốt lõi: chọn nhật theo thiên thời, hợp địa lợi, nhân hòa; làm đúng ngày thì việc dễ thành, trái ngày thì dễ trắc trở."
    },
    {
      "name_han": "元始無量度人上品妙經通義",
      "full_vn": "Nguyên Thủy Vô Lượng Độ Nhân Thượng Phẩm Diệu Kinh Thông Nghĩa giảng Kinh Độ Nhân: Nguyên Thủy Thiên Tôn nói kinh ở Bích Lạc Không Ca, phóng đại quang minh, tuyên 'độ nhân vô lượng'. Kinh dạy: tụng kinh thì thiên địa thanh, quỷ thần kính, chết được thăng, sống được kéo dài. 'Nguyên thủy động lực' mở ra cửa sinh tử; 'vô lượng' là lượng đức độ khắp. Thông Nghĩa làm rõ: thân khẩu ý thanh tịnh, trì chú, tin kính thì được cứu độ. Cốt lõi: lấy thanh tĩnh, từ bi, trì tụng để độ mình và độ người."
    },
    {
      "name_han": "元始無量度人上品妙經內義",
      "full_vn": "Nguyên Thủy Vô Lượng Độ Nhân Thượng Phẩm Diệu Kinh Nội Nghĩa giảng nghĩa bên trong Kinh Độ Nhân: chữ 'độ' là đưa linh hồn ra khỏi luân hồi; 'nhân' là chúng sinh trong thập phương. Nội nghĩa chỉ: khí trong thân tương ứng với khí trời; tụng kinh là vận hành chân khí, khai thông cửu khiếu, hợp với thiên đạo. 'Đại Phạn ẩn ngữ' là mật chú của trời, trì thì hồn phách an. Giải thích: ngoài là nghi thức, trong là luyện khí thần. Cốt lõi: kinh ngoài cứu thế, kinh trong tu thân; ngoài độ người, trong độ mình."
    },
    {
      "name_han": "靈寶無量度人上品妙經符圖",
      "full_vn": "Linh Bảo Vô Lượng Độ Nhân Thượng Phẩm Diệu Kinh Phù Đồ chép phù, đồ, ấn liên quan Kinh Độ Nhân. Phù dùng để triệu thỉnh thiên binh, trấn tà, cứu hồn; đồ vẽ cung đế, sao, khí vận hành. Văn chỉ: khi vẽ phù phải tĩnh tâm, tắm gội, hướng đúng phương, niệm chú; phù không đúng nghi thì không linh. Phù Đồ gắn với nghi cúng tế, độ vong, cầu an. Cốt lõi: phù là hình của đạo khí, đồ là bản đồ thiên cơ; dùng đúng nghi, đúng tâm thì phù có hiệu, trái thì vô dụng."
    },
    {
      "name_han": "元始天尊說梓潼帝君本願經",
      "full_vn": "Nguyên Thủy Thiên Tôn Thuyết Tử Đồng Đế Quân Bản Nguyện Kinh: Thiên Tôn thuật nguyện gốc của Tử Đồng Đế Quân (Văn Xương). Đế Quân thề cứu kẻ nghèo học, mở đường khoa cử, phạt gian khuyến thiện, bảo hộ văn nghiệp. Kinh dạy: ai thành tâm cầu, giữ hiếu đễ, không dối trá, siêng học thì được phù hộ; ai gian tà, lừa dối thì bị xét. Bản nguyện: 'nguyện cho thiên hạ có chữ, có đức, có đường tiến thân chính đáng'. Cốt lõi: văn vận gắn đạo đức; học chữ phải học làm người."
    },
    {
      "name_han": "梓潼帝君化書",
      "full_vn": "Tử Đồng Đế Quân Hóa Thư chép các lần hóa thân của Văn Xương Đế Quân qua các đời: làm quan, làm thầy, làm thần, để giáo hóa dân, khuyến thiện, trừng ác, bảo vệ kẻ hiếu học. Sách kể: mỗi lần giáng thế, Đế Quân dùng đức và văn để chỉnh phong tục; ai trung hiếu được nâng, ai gian nịnh bị đọa. Hóa Thư nhấn: thần không xa người, người thiện thì thần gần. Cốt lõi: thiện ác có báo, văn giáo cứu đời; tu đức và học hành là đường hợp với hóa thân của Đế Quân."
    },
    {
      "name_han": "玄都律文",
      "full_vn": "Huyền Đô Luật Văn là bộ luật giới của đạo sĩ: cấm sát sinh, trộm cắp, tà dâm, vọng ngữ, uống rượu say; cấm lừa dối tín đồ, bán bùa giả, tham của cúng. Luật quy định cách mặc áo, hành nghi, giữ trai giới, đối đãi đồng đạo. Phạm giới nhẹ thì sám hối, nặng thì đuổi khỏi môn. Văn nhấn: luật là để giữ tâm thanh, thân tịnh, miệng đúng. Cốt lõi: không có giới thì đạo không thành; giữ luật là giữ mạng mạch tông môn và phúc đức cá nhân."
    },
    {
      "name_han": "要修科儀戒律鈔",
      "full_vn": "Yếu Tu Khoa Nghi Giới Luật Sao chép tóm nghi thức và giới luật cần tu: khoa nghi gồm trai đàn, sớ tấu, triều nguyên, độ vong; giới luật gồm ngũ giới, thập giới, bách bát giới. Sao dạy thứ tự hành nghi: tịnh thân, thiết đàn, thỉnh thánh, đọc kinh, dâng sớ, tạ sư. Giữ giới trước, hành khoa sau; giới không giữ thì khoa không linh. Cốt lõi: khoa nghi là hình thức giao cảm trời người, giới luật là gốc thanh tịnh; tu đúng nghi đúng giới thì cầu đảo có ứng."
    },
    {
      "name_han": "太上玄靈北斗本命延生真經註",
      "full_vn": "Thái Thượng Huyền Linh Bắc Đẩu Bản Mệnh Diên Sinh Chân Kinh Chú giải Kinh Bắc Đẩu: mỗi người có sao bản mệnh trong chòm Bắc Đẩu; lễ bái, tụng kinh đúng ngày sinh thì sao chiếu, tai qua nạn khỏi, thọ mệnh kéo dài. Chú giải rõ: Bắc Đẩu chủ sinh tử, giải ách, ban phúc. Tụng 'Bắc Đẩu chú' với tâm thành, ăn chay, không sát hại thì được che chở. Cốt lõi: bản mệnh liên sao trời; kính tinh, sửa đức, trì kinh thì diên sinh, tiêu tai."
    },
    {
      "name_han": "玄珠錄",
      "full_vn": "Huyền Châu Lục (ngữ lục Vương Huyền Lãm / truyền thống Trùng Huyền) nói về 'huyền châu' — chân tâm sáng suốt như ngọc. Lục dạy: Đạo không ngoài tâm; chấp có thì dính, chấp không thì rỗng; phải 'phi hữu phi vô' mới hợp huyền. Thấy tánh thì châu hiện, mê thì châu ẩn. Tu là phản chiếu tự tâm, không cầu bên ngoài. Cốt lõi: huyền châu là bản giác; dứt nhị biên, giữ trung đạo, thì châu sáng, đạo hiện trong một niệm."
    },
    {
      "name_han": "宗玄先生玄綱論",
      "full_vn": "Tông Huyền Tiên Sinh Huyền Cương Luận (Ngô Vân) lập cương lĩnh đạo giáo: Đạo là gốc, đức là dụng; vô vi là thể, hữu vi là quyền. Luận chia: đạo tính, đạo đức, đạo dụng; dạy người lấy hư tĩnh làm gốc, từ kiệm làm hành, bất tranh làm đức. Trị thân như trị quốc: ít dục, ít sự thì an. 'Huyền cương' là sợi chỉ xuyên suốt: hợp thiên địa, thuận tự nhiên. Cốt lõi: nắm cương thì mắt lưới mở; nắm Đạo thì muôn pháp có chỗ."
    },
    {
      "name_han": "盤山棲雲王真人語錄",
      "full_vn": "Bàn Sơn Thê Vân Vương Chân Nhân Ngữ Lục ghi lời Vương Chí Cẩn (Thê Vân): tu đạo cốt ở thanh tĩnh, ít muốn, trung thành với sư truyền. Ngữ lục khuyên: hàng ngày giữ tâm như nước lặng, đừng chạy theo danh lợi; ngồi thiền, dưỡng khí, hành thiện là ba việc thường. Gặp nghịch cảnh coi là luyện tâm. Cốt lõi: đạo ở chỗ bình thường; không cần kỳ quái, chỉ cần chân thật, bền bỉ, tâm không loạn thì khí tự hòa, thần tự sáng."
    },
    {
      "name_han": "道門經法相承次序",
      "full_vn": "Đạo Môn Kinh Pháp Tương Thừa Thứ Tự chép thứ bậc truyền thừa kinh pháp đạo giáo: từ Tam Động (Động Chân, Động Huyền, Động Thần) đến Tứ Phụ; kinh nào trước, kinh nào sau; pháp nào thuộc thượng thanh, linh bảo, chính nhất. Văn chỉ: học phải theo thứ tự, không nhảy cấp; nhận kinh phải có sư truyền, minh thệ. Thứ tự giữ cho tông chỉ không loạn. Cốt lõi: kinh pháp có nguồn, có dòng; đúng thừa truyền thì đạo chính, sai thừa truyền thì dễ tà ngụy."
    },
    {
      "name_han": "上清道類事相",
      "full_vn": "Thượng Thanh Đạo Loại Sự Tướng phân loại sự việc đạo Thượng Thanh: cung thất tiên cảnh, danh hiệu chân nhân, phục thực, tồn tư, phù lục, nghi thức. Sách sắp theo loại để người học tra cứu: ở đâu tu, thờ ai, dùng phép gì. 'Sự tướng' là hình tướng cụ thể của đạo pháp, không chỉ lý suông. Cốt lõi: Thượng Thanh lấy tồn tưởng, đăng chân, phục khí làm chính; biết loại biết tướng thì hành trì có chỗ bám, không mơ hồ."
    },
    {
      "name_han": "雲山集",
      "full_vn": "Vân Sơn Tập là thi văn, từ phú của đạo sĩ (thường gắn dòng Toàn Chân / ẩn sĩ núi mây): tả cảnh núi mây, chí xuất thế, lòng thanh hư. Tập nói: ở núi không phải trốn đời mà để nuôi đạo; mây đến mây đi như niệm khởi niệm diệt. Thơ khuyên buông danh lợi, giữ bản chân, lấy thiên nhiên làm bạn. Cốt lõi: văn để chở đạo; cảnh ngoài gợi tâm trong — mây nhàn, núi tĩnh, người cũng nên nhàn tĩnh theo."
    },
    {
      "name_han": "洞玄金玉集",
      "full_vn": "Động Huyền Kim Ngọc Tập (Mã Đan Dương) thu thơ từ Toàn Chân: kim ngọc ví chân tính quý sạch. Tập dạy: đoạn trừ tửu sắc tài khí, giữ thanh bần, hòa với đồng đạo; luyện tâm như luyện đan, ngày ngày trừ xỉu. 'Kim' là cương quyết dứt dục, 'ngọc' là nhu hòa giữ đức. Cốt lõi: xuất gia là xuất tâm; không xuất tâm thì núi cao cũng tục. Giữ giới, nhẫn nhục, chân công tích lũy thì tính mệnh song tu có hy vọng."
    },
    {
      "name_han": "清和真人北遊語錄",
      "full_vn": "Thanh Hòa Chân Nhân Bắc Du Ngữ Lục ghi lời Doãn Chí Bình khi du phương phương Bắc: gặp đệ tử hỏi đạo, đáp bằng việc thực — nhẫn, khiêm, khổ, làm việc cho chúng. Ngữ lục nhấn: đạo không ở miệng mà ở bước chân; đi đâu cũng giữ thanh hòa. Dạy người mới: đừng ham thần thông, hãy lo sửa tính. Cốt lõi: Bắc du là hành đạo giữa đời; lấy hòa làm quý, lấy thanh làm gốc, lấy khổ hạnh và từ bi làm công phu thường ngày."
    },
    {
      "name_han": "黃庭內景玉經注",
      "full_vn": "Hoàng Đình Nội Cảnh Ngọc Kinh Chú giải Hoàng Đình: trong thân có cung đỉnh, thần linh cai quản từng tạng; 'nội cảnh' là cảnh trời trong người. Chú dạy: tồn tưởng thần tạng, nuốt nước bọt, điều tức, giữ tinh bất tiết thì trường sinh. 'Hoàng đình' là trung cung, nơi ý trụ. Kinh bảo: miệng tụng, tâm tồn, thân hành nhất trí. Cốt lõi: thân là vũ trụ nhỏ; nuôi thần, giữ khí, vững tinh — tam bảo đủ thì nội cảnh sáng, bệnh suy lui."
    },
    {
      "name_han": "黃帝陰符經疏",
      "full_vn": "Hoàng Đế Âm Phù Kinh Sớ giải 'xem trời thi hành, nắm cơ mà dùng': thiên cơ, địa cơ, nhân cơ tương tặc tương dụng. Sớ giảng: 'sát' không chỉ giết mà là chế ngự; biết thời, biết cơ thì thắng. 'Trộm' khí trời đất để nuôi thân là hợp đạo, không phải gian. Tâm là cơ, theo vật thì mất, làm chủ thì còn. Cốt lõi: Âm Phù dạy xem cơ trời mà hành sự; minh cơ, kiệm dục, hợp thời — thân an, việc thành, hợp với đạo binh và đạo dưỡng sinh."
    }
  ]
}
